(_je2.chapters = _je2.chapters || []).push(
  { n:27, summary:"God told Jeremiah to make bonds and wooden yokes, wear them on his own neck, and send them by visiting ambassadors to the kings of Edom, Moab, Ammon, Tyre, and Zidon. The message: the God who made the earth by His great power has given all these lands to Nebuchadnezzar of Babylon, His servant. Nations that refuse to put their neck under Babylon's yoke will be punished with sword, famine, and pestilence until they are consumed, while nations that submit may keep tilling their own land. Jeremiah told Zedekiah to serve Babylon and live, and warned the priests and people not to listen to prophets promising the temple vessels would soon return from Babylon. Those vessels would be carried away and stay there until the day God visited them and brought them back.",
  context:"Given at the beginning of the reign of Jehoiakim, as messengers from Edom, Moab, Ammon, Tyre, and Zidon came to Jerusalem.",
  keyVerses:[
    { ref:"Jeremiah 27:6", text:"And now have I given all these lands into the hand of Nebuchadnezzar the king of Babylon, my servant; and the beasts of the field have I given him also to serve him." },
    { ref:"Jeremiah 27:8", text:"And it shall come to pass, that the nation and kingdom which will not serve the same Nebuchadnezzar the king of Babylon, and that will not put their neck under the yoke of the king of Babylon" },
    { ref:"Jeremiah 27:12", text:"I spake also to Zedekiah king of Judah according to all these words, saying, Bring your necks under the yoke of the king of Babylon, and serve him and his people, and live." }
  ],
  takeaway:"God sets up and removes kingdoms; submitting to His appointed discipline preserves life where rebellion destroys it.",
  quiz:[
    { q:"What object did the Lord tell Jeremiah to make and wear as a sign to the nations?", choices:["Bonds and yokes","A hair-covered loincloth","A pot of boiling water","An earthen vessel"], a:0, why:"The Lord said, Make thee bonds and yokes, and put them upon thy neck; copies went to the surrounding kings by their messengers." },
    { q:"What did the Lord say would happen to a nation that refused to serve Nebuchadnezzar?", choices:["It would be ruled by Pharaoh of Egypt instead","It would be punished with sword, famine, and pestilence","It would be blessed with a faithful remnant","It would be exalted above Babylon"], a:1, why:"The Lord said He would punish such a nation with the sword, famine, and pestilence until consumed, while nations that submitted could remain in their own land." },
    { q:"Why did the Lord require the nations to submit to Babylon's yoke?", choices:["Babylon's army was the largest in the world","The nations had no kings of their own","God had given all these lands to Nebuchadnezzar, His servant","Jeremiah wanted peace for personal safety"], a:2, why:"The Lord declared He made the earth by His great power and outstretched arm and had given all these lands to Nebuchadnezzar, whom He called His servant." }
  ] },
  { n:28, summary:"Hananiah of Gibeon stepped into the temple and announced in the Lord's name that the yoke of Babylon was already broken: within two full years the temple vessels and all the captives, including Jeconiah, would come home. Jeremiah answered, Amen, may the Lord do so, but reminded the crowd that prophets of peace are proven true only when their words come to pass. Hananiah then snatched the wooden yoke off Jeremiah's neck and smashed it. The Lord sent Jeremiah back with a harder word: wooden yokes would become yokes of iron, because God had put all nations under Nebuchadnezzar's power. Jeremiah told Hananiah that the Lord had not sent him, that he was making the people trust a lie, and that he would die that year. Hananiah died in the seventh month.",
  context:"The same year as Jeremiah's yoke sign, in the fourth year and fifth month under Zedekiah, Hananiah of Gibeon broke the yoke in the temple.",
  keyVerses:[
    { ref:"Jeremiah 28:2", text:"Thus speaketh the LORD of hosts, the God of Israel, saying, I have broken the yoke of the king of Babylon." },
    { ref:"Jeremiah 28:9", text:"The prophet which prophesieth of peace, when the word of the prophet shall come to pass, then shall the prophet be known, that the LORD hath truly sent him." },
    { ref:"Jeremiah 28:13", text:"Go and tell Hananiah, saying, Thus saith the LORD; Thou hast broken the yokes of wood; but thou shalt make for them yokes of iron." }
  ],
  takeaway:"A prophet is proven by fulfilled truth, not by popularity; God is not mocked by leaders who promise peace He has not spoken.",
  quiz:[
    { q:"What did Hananiah do to Jeremiah's yoke?", choices:["He polished it and hung it in the temple","He refused to touch it","He put it on his own neck","He took it off Jeremiah's neck and broke it"], a:3, why:"Hananiah took the yoke from off the prophet Jeremiah's neck and brake it, claiming the Lord would break Babylon's yoke over all nations within two years." },
    { q:"How soon did Hananiah say the temple vessels and the captives would return?", choices:["After seventy years","Within two full years","Within seven days","In the seventh month of that year"], a:1, why:"Hananiah prophesied that within two full years all the vessels of the Lord's house and Jeconiah with the captives would be brought back from Babylon." },
    { q:"What sentence did the Lord pronounce on Hananiah for making the people trust a lie?", choices:["He would live as a prisoner in Babylon","He would never prophesy again","He would die that same year","He would wander in the wilderness"], a:2, why:"Jeremiah told him the Lord had not sent him and that he would die that year because he taught rebellion against the Lord; Hananiah died in the seventh month." }
  ] },
  { n:29, summary:"Jeremiah wrote a letter to the elders, priests, prophets, and people Nebuchadnezzar had carried to Babylon, sending it by Elasah and Gemariah. His counsel was surprising: settle down. Build houses, plant gardens, marry and have children, and seek the peace of the city, praying for it, because their peace was tied to its peace. God promised that after seventy years in Babylon He would visit them, perform His good word, and bring them home. The famous heart of the letter: I know the thoughts I think toward you, thoughts of peace and not of evil, to give you an expected end; they would find Him when they searched with all their heart. The letter also condemned lying prophets, two of whom the king of Babylon would roast in the fire, and Shemaiah, whose seed would have no man dwelling among the people.",
  context:"A letter Jeremiah sent from Jerusalem to the elders, priests, prophets, and people whom Nebuchadnezzar had already carried captive to Babylon.",
  keyVerses:[
    { ref:"Jeremiah 29:10", text:"For thus saith the LORD, That after seventy years be accomplished at Babylon I will visit you, and perform my good word toward you, in causing you to return to this place." },
    { ref:"Jeremiah 29:11", text:"For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end." },
    { ref:"Jeremiah 29:13", text:"And ye shall seek me, and find me, when ye shall search for me with all your heart." }
  ],
  takeaway:"Bloom where God plants you: seek the welfare of your city, trust His seventy-year plans, and search for Him with all your heart.",
  quiz:[
    { q:"What practical life did the Lord tell the exiles in Babylon to build?", choices:["Stay armed by the river awaiting rescue","Build houses, plant gardens, and seek the peace of the city","Refuse all work until freedom came","Wander back toward Judah in secret groups"], a:1, why:"The letter said to build houses and dwell in them, plant gardens, marry and multiply, and pray for the peace of the city where God had carried them." },
    { q:"How long did the Lord say the Babylonian captivity would last before He brought them back?", choices:["Forty years","Seven years","Three generations","Seventy years"], a:3, why:"The Lord said that after seventy years be accomplished at Babylon He would visit them and perform His good word in causing them to return to their place." },
    { q:"Which promise shows God's heart toward the exiles in this letter?", choices:["I know the thoughts that I think toward you, thoughts of peace","The sword shall never enter Babylon","Your captivity shall end tomorrow","Jerusalem shall never fall"], a:0, why:"The Lord declared His thoughts toward the captives were thoughts of peace and not of evil, to give them an expected end." }
  ] },
  { n:30, summary:"Write the words in a book, the Lord commanded, for the days were coming when He would bring again the captivity of Israel and Judah to the land of their fathers. The chapter paints a day of trembling so severe it is called the time of Jacob's trouble, yet Jacob would be saved out of it. God would break the yoke from Israel's neck so they could serve the Lord their God and David their king, whom He would raise up. Though the wound looked incurable and every ally had forgotten Zion, the Lord Himself promised to restore health and heal her wounds, because men called her an outcast whom no one sought. The city would be rebuilt on her own heap, thanksgiving would ring out, children would flourish, and the covenant would stand again: ye shall be my people, and I will be your God.",
  context:"Part of the Lord's command to write His words in a book, promising to bring again the captivity of Israel and Judah.",
  keyVerses:[
    { ref:"Jeremiah 30:7", text:"Alas! for that day is great, so that none is like it: it is even the time of Jacob's trouble; but he shall be saved out of it." },
    { ref:"Jeremiah 30:10", text:"Therefore fear thou not, O my servant Jacob, saith the LORD; neither be dismayed, O Israel: for, lo, I will save thee from afar, and thy seed from the land of their captivity; and Jacob shall return, and shall be in rest, and be quiet, and none shall make him afraid." },
    { ref:"Jeremiah 30:17", text:"For I will restore health unto thee, and I will heal thee of thy wounds, saith the LORD; because they called thee an Outcast, saying, This is Zion, whom no man seeketh after." }
  ],
  takeaway:"God corrects in measure but never makes a full end of His covenant people; His healing follows His chastening.",
  quiz:[
    { q:"What name does the chapter give to the coming day of dread?", choices:["The hour of the harlot","The time of Jacob's trouble","The day of Jezreel","The night of weeping"], a:1, why:"The Lord called that unparalleled day the time of Jacob's trouble, and promised that he shall be saved out of it." },
    { q:"Whom does the chapter promise Israel will serve when the yoke is broken?", choices:["Pharaoh of Egypt","The princes of the captivity","The LORD their God and David their king","The priests of Beth-el"], a:2, why:"The Lord said He would break the yoke from off their neck and burst their bonds, and they would serve the LORD their God and David their king, whom He would raise up." },
    { q:"What does God's promise to heal Zion's incurable wound teach about His mercy?", choices:["Mercy means judgment was never real","God never corrects those He loves","Restoration comes only through foreign allies","God wounds in correction, then He Himself restores"], a:3, why:"Because of multiplied sins the Lord had wounded Zion with the chastisement of a cruel one, yet He promised, I will restore health unto thee, and I will heal thee of thy wounds." }
  ] },
  { n:31, summary:"This consolation chapter gathers some of Jeremiah's brightest promises. The Lord loved Israel with an everlasting love and would rebuild her: watchmen on Ephraim's hills would call people back to Zion, a great company would return from the north country, including the blind and the lame, and God would lead them home like a shepherd gathering his flock. Rachel weeping for her children was told to dry her tears, for her children would come again to their own border. Ephraim, chastened like an untrained bullock, repented, and God's heart was moved to mercy. Then came the promise of a new covenant, different from the covenant God made when He brought them out of Egypt, which they broke: He would put His law in their inward parts and write it in their hearts, all would know Him, and He would forgive their iniquity and remember their sin no more. Jerusalem would be rebuilt and never plucked down again.",
  context:"The continuing book of consolation, promising a gathered Israel, a new covenant, and a rebuilt Jerusalem.",
  keyVerses:[
    { ref:"Jeremiah 31:3", text:"The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee." },
    { ref:"Jeremiah 31:33", text:"But this shall be the covenant that I will make with the house of Israel; After those days, saith the LORD, I will put my law in their inward parts, and write it in their hearts; and will be their God, and they shall be my people." },
    { ref:"Jeremiah 31:34", text:"And they shall teach no more every man his neighbour, and every man his brother, saying, Know the LORD: for they shall all know me, from the least of them unto the greatest of them, saith the LORD: for I will forgive their iniquity, and I will remember their sin no more." }
  ],
  takeaway:"The new covenant writes God's law on willing hearts, where all can know Him and find sins remembered no more.",
  quiz:[
    { q:"What tender family scene pictures Rachel mourning in this chapter?", choices:["Rachel weeping for her children, refusing comfort","Hannah praying for a son","Rizpah guarding the bones","Mary weeping at the tomb"], a:0, why:"A voice was heard in Ramah, Rahel weeping for her children and refusing to be comforted; the Lord told her to refrain from tears, for her children would come again to their own border." },
    { q:"In the new covenant, where does God promise to put His law?", choices:["On pillars by every city gate","In scrolls read only by priests","In their inward parts, written in their hearts","In tablets of stone kept in an ark"], a:2, why:"The Lord promised to put His law in their inward parts and write it in their hearts, so that all would know Him and He would forgive their iniquity." },
    { q:"What does the promise of an everlasting love teach about God's dealings with His covenant people?", choices:["His love ends when they are scattered","His love depends on their perfect record","His love is only for the tribe of Judah","His love draws them even while He corrects them"], a:3, why:"The Lord said He had loved Israel with an everlasting love and drawn them with lovingkindness, even as He oversaw their chastening and promised their return." }
  ] },
  { n:32, summary:"With Babylon's army besieging Jerusalem and Jeremiah locked in the court of the prison for prophesying the city's fall, the Lord told him that his cousin Hanameel would come offering to sell his field at Anathoth. When Hanameel appeared just as foretold, Jeremiah weighed out seventeen shekels of silver, signed and sealed the deed, took witnesses, and handed the evidence to Baruch with orders to store both copies in an earthen vessel to last many days. The purchase looked foolish with the Chaldeans at the gates, and Jeremiah admitted his confusion in prayer. God answered: nothing is too hard for Him. The city would indeed fall and burn, yet He would gather His people from all countries, make an everlasting covenant with them, and fields would be bought with deeds and witnesses in the land again.",
  context:"In the tenth year of Zedekiah, the eighteenth year of Nebuchadrezzar, while the Babylonian army besieged Jerusalem and Jeremiah sat in the court of the prison.",
  keyVerses:[
    { ref:"Jeremiah 32:15", text:"For thus saith the LORD of hosts, the God of Israel; Houses and fields and vineyards shall be possessed again in this land." },
    { ref:"Jeremiah 32:17", text:"Ah Lord GOD! behold, thou hast made the heaven and the earth by thy great power and stretched out arm, and there is nothing too hard for thee:" },
    { ref:"Jeremiah 32:27", text:"Behold, I am the LORD, the God of all flesh: is there any thing too hard for me?" }
  ],
  takeaway:"Faith acts on God's promises even when the city is falling, because nothing is too hard for the Lord.",
  quiz:[
    { q:"How much did Jeremiah pay Hanameel for the field at Anathoth?", choices:["Fifty pieces of bronze","Thirty pence","A hundred talents","Seventeen shekels of silver"], a:3, why:"Jeremiah bought the field and weighed him the money, even seventeen shekels of silver, then sealed the deed and took witnesses." },
    { q:"What did Jeremiah tell Baruch to do with the deed copies?", choices:["Put them in an earthen vessel to last many days","Nail them to the temple door","Send them to the exiles in Babylon","Bury them under the altar"], a:0, why:"The Lord commanded that both the sealed and the open evidence of purchase be put in an earthen vessel, that they may continue many days." },
    { q:"When Jeremiah wondered why God told him to buy land about to fall to the Chaldeans, what answer came?", choices:["The field is worthless anyway","Babylon will retreat within a year","The Chaldeans will spare Anathoth","Is there any thing too hard for me?"], a:3, why:"God answered that He is the LORD, the God of all flesh, and nothing is too hard for Him; He would both bring judgment on the city and gather His people again." }
  ] },
  { n:33, summary:"While still shut up in the prison court, Jeremiah received the word a second time. First came a standing invitation: Call unto me, and I will answer thee, and shew thee great and mighty things which thou knowest not. Then the Lord explained what those things were. The sick city would be brought health and cure, the captivity of Judah and Israel would return, iniquity would be cleansed and pardoned, and the streets that would soon lie empty without man and beast would again ring with the voice of joy, the bridegroom and the bride, and worshipers praising the Lord, whose mercy endureth for ever. Shepherds would again feed flocks in Judah's hills. God pledged to perform the good thing He had promised: a Branch of righteousness would grow up unto David, Judah would be saved, Jerusalem would dwell safely, and David's throne would lack no heir as long as day and night kept their order.",
  context:"The word of the LORD came a second time to Jeremiah while he was still shut up in the court of the prison during the siege.",
  keyVerses:[
    { ref:"Jeremiah 33:3", text:"Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not." },
    { ref:"Jeremiah 33:6", text:"Behold, I will bring it health and cure, and I will cure them, and will reveal unto them the abundance of peace and truth." },
    { ref:"Jeremiah 33:15", text:"In those days, and at that time, will I cause the Branch of righteousness to grow up unto David; and he shall execute judgment and righteousness in the land." }
  ],
  takeaway:"Call upon God in the darkest siege; He answers and shows great and mighty things, including mercy that restores.",
  quiz:[
    { q:"What did the Lord invite Jeremiah to do while shut up in the prison court?", choices:["Sell his field at once","Escape toward the land of Benjamin","Call unto me, and I will answer thee","Write a letter to Baruch"], a:2, why:"The Lord said, Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not." },
    { q:"Whose voice would again be heard in Jerusalem's streets after the desolation?", choices:["Only weeping mourners","Marching soldiers","Babylonian tax collectors","The bridegroom and the bride, praising the LORD"], a:3, why:"The Lord promised the voice of joy and gladness, of the bridegroom and the bride, and of those praising the LORD, whose mercy endureth for ever." },
    { q:"What unbreakable pattern did God give as proof that David's line would continue?", choices:["As long as day and night keep their seasons","As long as the temple stands","As long as Israel keeps the law","As long as Jerusalem has walls"], a:0, why:"If ye can break my covenant of the day and of the night, then may my covenant be broken with David — an impossible condition that secures the promise." }
  ] },
  { n:34, summary:"The Lord sent word to Zedekiah as Nebuchadnezzar fought against Jerusalem and the last fortified cities, Lachish and Azekah: the city would burn, yet the king would die in peace, not by the sword. Jerusalem's people had made a covenant in the temple to proclaim liberty, letting every Hebrew manservant and maidservant go free. They obeyed at first, then reversed themselves and dragged the freed servants back into bondage. The Lord reminded them that His law from the Exodus days required releasing Hebrew servants after six years, a command their fathers had also ignored. Because they profaned His name by breaking the covenant cut before Him, He would proclaim a liberty of His own for them: liberty to the sword, to the pestilence, and to the famine, and the Babylonian army would return, take the city, and burn it with fire.",
  context:"Spoken when Nebuchadnezzar fought against Jerusalem and the remaining defenced cities of Judah, Lachish and Azekah, in the days of Zedekiah.",
  keyVerses:[
    { ref:"Jeremiah 34:8", text:"This is the word that came unto Jeremiah from the LORD, after that the king Zedekiah had made a covenant with all the people which were at Jerusalem, to proclaim liberty unto them;" },
    { ref:"Jeremiah 34:15", text:"And ye were now turned, and had done right in my sight, in proclaiming liberty every man to his neighbour; and ye had made a covenant before me in the house which is called by my name:" },
    { ref:"Jeremiah 34:17", text:"Therefore thus saith the LORD; Ye have not hearkened unto me, in proclaiming liberty, every one to his brother, and every man to his neighbour: behold, I proclaim a liberty for you, saith the LORD, to the sword, to the pestilence, and to the famine;" }
  ],
  takeaway:"Breaking a covenant of liberty brings bondage; the Lord takes His covenants, and our word to Him, with utter seriousness.",
  quiz:[
    { q:"What covenant had Zedekiah and the people just made in Jerusalem?", choices:["To fight to the last man","To proclaim liberty to their Hebrew servants","To surrender the city quietly","To send gold to Pharaoh"], a:1, why:"The king made a covenant with all the people to proclaim liberty, letting every Hebrew manservant and maidservant go free." },
    { q:"What did the people do shortly after freeing their servants?", choices:["They freed more servants","They brought the servants back into subjection","They burned the temple records","They fled to Egypt"], a:1, why:"Afterward they turned and caused the servants and handmaids whom they had let go free to return and be brought into subjection again." },
    { q:"What ironic judgment did God pronounce for breaking the liberty covenant?", choices:["Your servants will rule over you","You will serve Egypt forever","Your names will be blotted out","I proclaim a liberty for you, to the sword, to the pestilence, and to the famine"], a:3, why:"Because they proclaimed liberty and then revoked it, the Lord proclaimed for them a liberty to sword, pestilence, and famine, and the Babylonian army would return and burn the city." }
  ] },
  { n:35, summary:"In Jehoiakim's days the Lord sent Jeremiah to test the Rechabites, a clan descended from Jonadab son of Rechab. Jeremiah brought them into a temple chamber and set bowls of wine before them, commanding them to drink. They refused, citing their father's standing command: drink no wine, build no houses, sow no seed, plant no vineyard, but dwell in tents all their days. They had kept that rule their whole lives, coming into Jerusalem only for fear of the Chaldean and Syrian armies. The Lord told the men of Judah to take note: Jonadab's sons obeyed their father's words, spoken generations earlier, while Judah would not listen to God Himself, though He rose early and sent prophets again and again. Judgment would fall on Judah, but the Rechabites received a blessing: Jonadab would never lack a man standing before the Lord.",
  context:"In the days of Jehoiakim son of Josiah, when Jeremiah brought the Rechabites into a temple chamber and set wine before them.",
  keyVerses:[
    { ref:"Jeremiah 35:8", text:"Thus have we obeyed the voice of Jonadab the son of Rechab our father in all that he hath charged us, to drink no wine all our days, we, our wives, our sons, nor our daughters;" },
    { ref:"Jeremiah 35:14", text:"The words of Jonadab the son of Rechab, that he commanded his sons not to drink wine, are performed; for unto this day they drink none, but obey their father's commandment: notwithstanding I have spoken unto you, rising early and speaking; but ye hearkened not unto me." },
    { ref:"Jeremiah 35:19", text:"Therefore thus saith the LORD of hosts, the God of Israel; Jonadab the son of Rechab shall not want a man to stand before me for ever." }
  ],
  takeaway:"Faithful obedience to God outshines the example of men, yet even a father's long-kept command puts Judah's disobedience to shame.",
  quiz:[
    { q:"Whose commandment had the Rechabites obeyed for generations?", choices:["Jonadab the son of Rechab","Jaazaniah the son of Jeremiah","Nebuchadrezzar of Babylon","Josiah king of Judah"], a:0, why:"They said, We will drink no wine: for Jonadab the son of Rechab our father commanded us; they also kept his rules about tents, houses, and vineyards." },
    { q:"What test did Jeremiah set before the Rechabites?", choices:["He offered them houses in Jerusalem","He commanded them to plant a vineyard","He set pots of wine and cups before them and said, Drink ye wine","He asked them to join the army"], a:2, why:"Jeremiah brought them into a chamber of the temple and set before them pots full of wine and cups, but they refused because of their father's command." },
    { q:"What contrast does the Lord draw from the Rechabites' obedience?", choices:["Wine is always forbidden to the faithful","Tent-dwelling is holier than building houses","Obedience to men replaces obedience to God","Jonadab's sons obeyed their father, while Judah would not obey God Himself"], a:3, why:"The Lord noted that the sons of Jonadab performed their father's commandment, while Judah would not hearken to God, who rose early and sent prophets again and again." }
  ] },
  { n:36, summary:"The fourth year of Jehoiakim brought a command: take a roll of a book and write all the words spoken against Israel, Judah, and the nations since Josiah's days, hoping the people would hear and turn so God could forgive them. Because Jeremiah was shut up, Baruch wrote the words from his mouth and read them publicly at the temple on a fast day. Michaiah heard them and reported to the princes, who summoned Baruch to read again. Alarmed, they hid Baruch and Jeremiah, then told the king. Jehudi read the roll before Jehoiakim in his winter house; after three or four leaves the king cut it with a penknife and burned it in the fire, unafraid, ignoring princes who begged him not to. He ordered Baruch and Jeremiah seized, but the Lord hid them and commanded another roll, with many like words added.",
  context:"In the fourth year of Jehoiakim the roll was written, and in his fifth year, ninth month, Baruch read it publicly before it was burned.",
  keyVerses:[
    { ref:"Jeremiah 36:2", text:"Take thee a roll of a book, and write therein all the words that I have spoken unto thee against Israel, and against Judah, and against all the nations, from the day I spake unto thee, from the days of Josiah, even unto this day." },
    { ref:"Jeremiah 36:23", text:"And it came to pass, that when Jehudi had read three or four leaves, he cut it with the penknife, and cast it into the fire that was on the hearth, until all the roll was consumed in the fire that was on the hearth." },
    { ref:"Jeremiah 36:28", text:"Take thee again another roll, and write in it all the former words that were in the first roll, which Jehoiakim the king of Judah hath burned." }
  ],
  takeaway:"Rejecting God's word does not destroy it; the burned roll was rewritten, and every word stood against the king.",
  quiz:[
    { q:"What did Jehoiakim do as Jehudi read the roll to him?", choices:["He read it aloud to the people","He cut it with a penknife and cast it into the fire","He wept and rent his clothes","He copied it and sent it to Babylon"], a:1, why:"After three or four leaves the king cut the roll with the penknife and burned it on the hearth, and neither he nor his servants feared." },
    { q:"Who wrote the roll from Jeremiah's mouth?", choices:["Baruch the son of Neriah","Elnathan the son of Achbor","Jehudi the son of Nethaniah","Gemariah the son of Shaphan"], a:0, why:"Jeremiah called Baruch the son of Neriah, and Baruch wrote from Jeremiah's mouth all the words of the LORD upon a roll of a book." },
    { q:"What does this chapter show about the word of God and those who reject it?", choices:["Burning the scroll could not destroy the word, which was written again","God's word fails when leaders reject it","Kings may edit prophecy to taste","Scrolls matter more than hearts"], a:0, why:"The Lord commanded another roll with all the former words, and many like words were added; the king who burned it lost his throne and his burial honor." }
  ] },
  { n:37, summary:"Zedekiah sent messengers asking Jeremiah to pray. When Pharaoh's army marched out of Egypt, the Chaldeans lifted the siege of Jerusalem, and hopes rose that the invaders were gone for good. The Lord said otherwise: Pharaoh's army would return home, the Chaldeans would come back, take the city, and burn it with fire. Even if the Judeans smote the whole Chaldean army and only wounded men remained, those wounded men would rise in their tents and burn the city. When Jeremiah set out for the land of Benjamin, Captain Irijah arrested him at the gate of Benjamin, accusing him of defecting to the Chaldeans. The princes beat him and imprisoned him in Jonathan the scribe's house. Zedekiah later questioned him secretly and still heard the same word; Jeremiah asked only not to be sent back to Jonathan's house, so the king kept him in the court of the prison on daily bread.",
  context:"During Zedekiah's reign, when Pharaoh's army marched out of Egypt and the Chaldean siege of Jerusalem briefly lifted.",
  keyVerses:[
    { ref:"Jeremiah 37:9", text:"Thus saith the LORD; Deceive not yourselves, saying, The Chaldeans shall surely depart from us: for they shall not depart." },
    { ref:"Jeremiah 37:10", text:"For though ye had smitten the whole army of the Chaldeans that fight against you, and there remained but wounded men among them, yet should they rise up every man in his tent, and burn this city with fire." },
    { ref:"Jeremiah 37:17", text:"Then Zedekiah the king sent, and took him out: and the king asked him secretly in his house, and said, Is there any word from the LORD? And Jeremiah said, There is: for, said he, thou shalt be delivered into the hand of the king of Babylon." }
  ],
  takeaway:"Partial relief in a siege is not deliverance; trust God's whole word, not the hopeful headlines of the moment.",
  quiz:[
    { q:"What made the Chaldeans temporarily lift the siege of Jerusalem?", choices:["A plague in their camp","Pharaoh's army came out of Egypt","News of a revolt in Babylon","A peace treaty with Zedekiah"], a:1, why:"When the Chaldeans that besieged Jerusalem heard tidings of Pharaoh's army come forth out of Egypt, they departed from the city." },
    { q:"What did the Lord say would happen even if the Judeans killed all but the wounded Chaldeans?", choices:["The Chaldeans would retreat to Riblah","Egypt would defend the city","The wounded would rise up in their tents and burn the city","The siege would end in peace"], a:2, why:"The Lord said though they smote the whole Chaldean army and only wounded men remained, those men would rise up every man in his tent and burn the city with fire." },
    { q:"Who arrested Jeremiah at the gate of Benjamin, claiming he was falling away to the Chaldeans?", choices:["Irijah, a captain of the ward","Jehucal the son of Shelemiah","Ebed-melech the Ethiopian","Zephaniah the priest"], a:0, why:"Irijah the son of Shelemiah took Jeremiah at the gate of Benjamin and brought him to the princes, who beat him and put him in the house of Jonathan the scribe." }
  ] },
  { n:38, summary:"Jeremiah kept saying that whoever stayed in Jerusalem would die by sword, famine, and pestilence, but whoever went out to the Chaldeans would live. The princes told Zedekiah the prophet was weakening the soldiers and demanded his death; the king said, behold, he is in your hand. They lowered Jeremiah by cords into a dungeon where there was no water, only mire, and he sank in the mire. Ebed-melech, an Ethiopian eunuch in the king's house, told the king the men had done evil and Jeremiah would starve; Zedekiah gave him thirty men, and Ebed-melech lowered old rags to pad Jeremiah's arms and drew him up. Zedekiah then met Jeremiah secretly and swore to spare him, and Jeremiah repeated the choice: go out to Babylon's princes and live, or stay and see the city burn. Fearing mockery, Zedekiah kept the meeting hidden, and Jeremiah remained in the prison court until Jerusalem was taken.",
  context:"In Jerusalem's last days, when the princes cast Jeremiah into a miry dungeon for preaching that surrender to Babylon meant life.",
  keyVerses:[
    { ref:"Jeremiah 38:6", text:"Then took they Jeremiah, and cast him into the dungeon of Malchiah the son of Hammelech, that was in the court of the prison: and they let down Jeremiah with cords. And in the dungeon there was no water, but mire: so Jeremiah sunk in the mire." },
    { ref:"Jeremiah 38:17", text:"Then said Jeremiah unto Zedekiah, Thus saith the LORD, the God of hosts, the God of Israel; If thou wilt assuredly go forth unto the king of Babylon's princes, then thy soul shall live, and this city shall not be burned with fire; and thou shalt live, and thine house:" },
    { ref:"Jeremiah 38:20", text:"But Jeremiah said, They shall not deliver thee. Obey, I beseech thee, the voice of the LORD, which I speak unto thee: so it shall be well unto thee, and thy soul shall live." }
  ],
  takeaway:"Speaking truth may cost comfort and freedom, but honest counselors and rescuers like Ebed-melech serve God's purpose.",
  quiz:[
    { q:"Where did the princes lower Jeremiah, where there was no water but mire?", choices:["The house of Jonathan the scribe","The dungeon of Malchiah in the prison court","A cistern at Bethlehem","The court of the guard tower"], a:1, why:"They cast Jeremiah into the dungeon of Malchiah the son of Hammelech and let him down with cords; in the dungeon was no water but mire, and he sunk in it." },
    { q:"Who told the king that Jeremiah would die of hunger in the dungeon?", choices:["Zephaniah the second priest","Gedaliah the governor","Ebed-melech the Ethiopian eunuch","Baruch the scribe"], a:2, why:"Ebed-melech told Zedekiah the men had done evil and Jeremiah was like to die of hunger where he was, since there was no more bread in the city." },
    { q:"What choice did Jeremiah set before Zedekiah in their secret meeting?", choices:["Flee by night to Ammon","Pay tribute to Pharaoh","Give himself up to his own princes","Go forth to the king of Babylon's princes and live, or stay and see the city burn"], a:3, why:"Jeremiah said if the king assuredly went forth to Babylon's princes his soul would live and the city would not burn; if not, the city would be taken and burned." }
  ] },
  { n:39, summary:"In the ninth year of Zedekiah, in the tenth month, Nebuchadrezzar's army besieged Jerusalem; in the eleventh year, on the ninth day of the fourth month, the city was broken up. Babylonian princes sat in the middle gate. Zedekiah and his warriors fled by night through the king's garden toward the plain, but the Chaldeans caught him in the plains of Jericho and brought him to Nebuchadnezzar at Riblah. There the king of Babylon killed Zedekiah's sons before his eyes, slew the nobles of Judah, put out Zedekiah's eyes, bound him in chains, and carried him to Babylon. The Chaldeans burned the king's house and the people's houses and broke down the walls. Nebuzar-adan carried the remnant captive but left the poor, giving them vineyards and fields. Jeremiah, released per Nebuchadnezzar's orders, went to Gedaliah. The Lord promised Ebed-melech deliverance because he trusted in the Lord.",
  context:"The siege began in Zedekiah's ninth year, tenth month; the city was broken up in his eleventh year, fourth month, ninth day.",
  keyVerses:[
    { ref:"Jeremiah 39:2", text:"And in the eleventh year of Zedekiah, in the fourth month, the ninth day of the month, the city was broken up." },
    { ref:"Jeremiah 39:7", text:"Moreover he put out Zedekiah's eyes, and bound him with chains, to carry him to Babylon." },
    { ref:"Jeremiah 39:18", text:"For I will surely deliver thee, and thou shalt not fall by the sword, but thy life shall be for a prey unto thee: because thou hast put thy trust in me, saith the LORD." }
  ],
  takeaway:"Judgment falls exactly as spoken, yet God remembers those who trusted Him and delivers mercy in the day of ruin.",
  quiz:[
    { q:"On what did the Babylonian princes sit when they entered the fallen city?", choices:["The temple steps","The middle gate","The altar of burnt offering","The king's throne"], a:1, why:"All the princes of the king of Babylon came in and sat in the middle gate when the city was broken up." },
    { q:"What did the king of Babylon do to Zedekiah at Riblah?", choices:["He made him governor of Judah","He sent him to Egypt","He spared his family entirely","He slew his sons before his eyes, then put out his eyes"], a:3, why:"The king of Babylon slew the sons of Zedekiah before his eyes and the nobles of Judah, put out Zedekiah's eyes, bound him in chains, and carried him to Babylon." },
    { q:"Why did the Lord promise to deliver Ebed-melech when the city fell?", choices:["Because he put his trust in the Lord","Because he was a Babylonian soldier","Because he paid a ransom","Because he owned fields in Anathoth"], a:0, why:"The Lord said Ebed-melech's life would be for a prey because thou hast put thy trust in me — the reward for the man who rescued Jeremiah from the mire." }
  ] },
  { n:40, summary:"After the fall, Nebuzar-adan the captain of the guard released Jeremiah at Ramah, where he had been taken bound in chains among the exiles. The Babylonian told Jeremiah that the Lord had brought exactly the evil He pronounced because the people sinned and would not obey His voice, then offered him a choice: come to Babylon and be well looked after, or go wherever he wished, with provisions and a reward. Jeremiah chose to join Gedaliah son of Ahikam, whom the king of Babylon had made governor over the remnant in Judah at Mizpah. Captains of scattered forces, including Ishmael, Johanan, and Seraiah, came with their men, and Gedaliah swore they would be safe if they served the king of Babylon. Jews returned from Moab, Ammon, and Edom and gathered wine and summer fruits in abundance. Johanan warned Gedaliah that Baalis king of the Ammonites had sent Ishmael to murder him and offered to strike first, but Gedaliah would not believe it.",
  context:"After Jerusalem fell, when Nebuzar-adan released Jeremiah at Ramah and the king of Babylon made Gedaliah governor over the remnant at Mizpah.",
  keyVerses:[
    { ref:"Jeremiah 40:2", text:"And the captain of the guard took Jeremiah, and said unto him, The LORD thy God hath pronounced this evil upon this place." },
    { ref:"Jeremiah 40:3", text:"Now the LORD hath brought it, and done according as he hath said: because ye have sinned against the LORD, and have not obeyed his voice, therefore this thing is come upon you." },
    { ref:"Jeremiah 40:9", text:"And Gedaliah the son of Ahikam the son of Shaphan sware unto them and to their men, saying, Fear not to serve the Chaldeans: dwell in the land, and serve the king of Babylon, and it shall be well with you." }
  ],
  takeaway:"Even a foreign captain could see the Lord had done as He said; the right response to correction is humble service.",
  quiz:[
    { q:"Whom did the king of Babylon make governor over the cities of Judah?", choices:["Ishmael the son of Nethaniah","Johanan the son of Kareah","Nebuzar-adan the captain","Gedaliah the son of Ahikam"], a:3, why:"The king of Babylon made Gedaliah the son of Ahikam governor over the cities of Judah, and Jeremiah went to dwell with him among the people." },
    { q:"Where did Gedaliah set up his administration?", choices:["Mizpah","Hebron","Ramah","Jericho"], a:0, why:"Jeremiah went to Gedaliah to Mizpah and dwelt among the people left in the land; the captains of the forces also gathered to him there." },
    { q:"What warning did Johanan bring Gedaliah about Ishmael?", choices:["Ishmael planned to burn Mizpah","Baalis king of the Ammonites had sent Ishmael to slay him","Ishmael had joined the Chaldeans","Ishmael was fleeing to Egypt"], a:1, why:"Johanan said Baalis the king of the Ammonites sent Ishmael to kill Gedaliah and offered to slay Ishmael secretly, but Gedaliah believed him not." }
  ] },
  { n:41, summary:"Ishmael son of Nethaniah, of the royal seed, came with ten men in the seventh month to eat bread with Governor Gedaliah at Mizpah, then killed him with the sword, along with the Jews and Chaldeans found there. Two days later, unaware of the murder, eighty mourners from Shechem, Shiloh, and Samaria arrived with offerings for the temple. Ishmael met them weeping, invited them to Gedaliah, then slaughtered them and cast their bodies into a great pit that Asa king of Judah had dug. Ten men were spared by promising hidden stores of wheat, barley, oil, and honey. Ishmael carried off the rest of the people at Mizpah, including the king's daughters, and headed for Ammon. Johanan son of Kareah pursued, caught him by the waters of Gibeon, and freed the captives; Ishmael escaped with eight men. Fearing Babylonian retaliation for the governor's murder, Johanan led the remnant to Chimham near Bethlehem, intending to flee into Egypt.",
  context:"In the seventh month after the fall of Jerusalem, when Ishmael of the royal seed murdered the governor Gedaliah at Mizpah.",
  keyVerses:[
    { ref:"Jeremiah 41:2", text:"Then arose Ishmael the son of Nethaniah, and the ten men that were with him, and smote Gedaliah the son of Ahikam the son of Shaphan with the sword, and slew him, whom the king of Babylon had made governor over the land." },
    { ref:"Jeremiah 41:8", text:"But ten men were found among them that said unto Ishmael, Slay us not: for we have treasures in the field, of wheat, and of barley, and of oil, and of honey. So he forbare, and slew them not among their brethren." },
    { ref:"Jeremiah 41:17", text:"And they departed, and dwelt in the habitation of Chimham, which is by Beth-lehem, to go to enter into Egypt," }
  ],
  takeaway:"One act of murderous treachery scattered a whole remnant; violence against God's order destroys far more than its target.",
  quiz:[
    { q:"What relationship gave Ishmael son of Nethaniah his standing?", choices:["A son of the high priest","A Chaldean officer","Of the seed royal","Gedaliah's brother"], a:2, why:"Ishmael the son of Nethaniah, of the seed royal, came with ten men and slew Gedaliah with the sword at a shared meal in Mizpah." },
    { q:"Why did Ishmael spare ten of the eighty mourners from Shechem, Shiloh, and Samaria?", choices:["They promised him hidden treasures of wheat, barley, oil, and honey","They swore loyalty to the Ammonites","They were priests of the temple","They showed him the king's daughters"], a:0, why:"Ten men said, Slay us not: for we have treasures in the field, of wheat, and of barley, and of oil, and of honey; so he forbare and slew them not." },
    { q:"Where did Johanan catch up with Ishmael and free the captives?", choices:["By the great waters in Gibeon","At the gates of Mizpah","In the plains of Jericho","At Tahpanhes in Egypt"], a:0, why:"Johanan found Ishmael by the great waters that are in Gibeon; the captured people turned to Johanan, but Ishmael escaped with eight men to the Ammonites." }
  ] },
  { n:42, summary:"The captains and all the people, from least to greatest, asked Jeremiah to pray for direction, promising before the Lord to obey whatever God said, whether good or evil. After ten days the answer came. If they stayed in the land, God would build and plant them and have mercy, and the king of Babylon, whom they feared, would deal mercifully with them. But if they set their faces to enter Egypt, seeking rest from war, trumpet sounds, and hunger, the very sword and famine they feared would overtake them there, and they would die by sword, famine, and pestilence in the place they desired to go. Jeremiah also exposed their hearts: they had dissembled, for the Lord already knew they would not obey. The chapter ends with the certainty of judgment on those who insist on Egypt.",
  context:"The remnant gathered near Bethlehem and asked Jeremiah to pray for the way they should walk, weighing a move to Egypt.",
  keyVerses:[
    { ref:"Jeremiah 42:6", text:"Whether it be good, or whether it be evil, we will obey the voice of the LORD our God, to whom we send thee; that it may be well with us, when we obey the voice of the LORD our God." },
    { ref:"Jeremiah 42:10", text:"If ye will still abide in this land, then will I build you, and not pull you down, and I will plant you, and not pluck you up: for I repent me of the evil that I have done unto you." },
    { ref:"Jeremiah 42:16", text:"Then it shall come to pass, that the sword, which ye feared, shall overtake you there in the land of Egypt, and the famine, whereof ye were afraid, shall follow close after you there in Egypt; and there ye shall die." }
  ],
  takeaway:"Ask God sincerely and obey the answer, whether good or evil; God sees the heart behind the request.",
  quiz:[
    { q:"How many days passed before the word of the Lord came to Jeremiah for the people?", choices:["Three days","Ten days","Forty days","Seventy days"], a:1, why:"It came to pass after ten days that the word of the LORD came unto Jeremiah, and he called all the people together." },
    { q:"What did the people promise when they asked Jeremiah to pray?", choices:["We will defend Mizpah to the end","We will follow Johanan into Egypt","We will obey the voice of the LORD, whether it be good or whether it be evil","We will build the temple again"], a:2, why:"They vowed before the Lord to do according to everything the Lord should send, whether good or evil, that it might be well with them." },
    { q:"What did the Lord promise if the remnant stayed in Judah?", choices:["Egypt would protect them","The Chaldeans would return at once","The famine would continue","I will build you, and not pull you down, and I will plant you, and not pluck you up"], a:3, why:"The Lord said if they still abode in the land He would build and plant them and show them mercies, so that the king of Babylon would have mercy on them." }
  ] },
  { n:43, summary:"Instead of submitting, Azariah, Johanan, and the proud men accused Jeremiah of lying and claimed Baruch was setting him against them to hand them to the Chaldeans. Ignoring the Lord's voice, Johanan and the captains took the whole remnant, men, women, children, the king's daughters, Jeremiah, and Baruch, and went into Egypt, reaching Tahpanhes. There the word of the Lord came to Jeremiah: he was to take great stones and hide them in the clay of the brickkiln at the entry of Pharaoh's house, in front of the men of Judah. The stones marked a throne: God would bring Nebuchadrezzar, His servant, to Egypt, set his royal pavilion over the hidden stones, and smite the land, delivering some to death, some to captivity, some to the sword. He would burn the houses of Egypt's gods and break the images of Beth-shemesh, and Nebuchadrezzar would go forth from there in peace.",
  context:"When the proud men rejected the Lord's answer and carried the whole remnant, including Jeremiah and Baruch, into Egypt as far as Tahpanhes.",
  keyVerses:[
    { ref:"Jeremiah 43:7", text:"So they came into the land of Egypt: for they obeyed not the voice of the LORD: thus came they even to Tahpanhes." },
    { ref:"Jeremiah 43:9", text:"Take great stones in thine hand, and hide them in the clay in the brickkiln, which is at the entry of Pharaoh's house in Tahpanhes, in the sight of the men of Judah;" },
    { ref:"Jeremiah 43:10", text:"And say unto them, Thus saith the LORD of hosts, the God of Israel; Behold, I will send and take Nebuchadrezzar the king of Babylon, my servant, and will set his throne upon these stones that I have hid; and he shall spread his royal pavilion over them." }
  ],
  takeaway:"Disobedience carries us into the very bondage we chose to flee; God's word still stands in the land we run to.",
  quiz:[
    { q:"Whom did the proud men blame for Jeremiah's message against Egypt?", choices:["Baruch the son of Neriah","Zedekiah the king","Nebuzar-adan","Ebed-melech"], a:0, why:"They accused Baruch of setting Jeremiah against them to deliver them into the hand of the Chaldeans, and refused to dwell in Judah." },
    { q:"Where did Jeremiah hide great stones as a sign?", choices:["Under the altar at Mizpah","In the clay of the brickkiln at the entry of Pharaoh's house in Tahpanhes","In the wall of Jerusalem","By the great waters of Gibeon"], a:1, why:"At Tahpanhes the Lord told him to hide stones in the brickkiln clay, declaring that Nebuchadrezzar would set his throne upon them." },
    { q:"What did the Lord say Nebuchadrezzar would do in Egypt?", choices:["Worship the queen of heaven","Rebuild the temple at Noph","Smite the land and burn the houses of the gods of Egypt","Marry Pharaoh's daughter"], a:2, why:"When he came he would smite the land, deliver some to death, captivity, and sword, kindle fire in the houses of Egypt's gods, and go forth from there in peace." }
  ] },
  { n:44, summary:"The word came to the Jews living in Egypt at Migdol, Tahpanhes, Noph, and Pathros. The Lord recited why Jerusalem lay desolate: idolatry, incense to other gods, and refusal to hear prophet after prophet. Now the fugitives in Egypt were doing the same, so the same judgments, sword, famine, and pestilence, would consume them, with only a small escaped number returning to Judah. The people answered Jeremiah defiantly: they would not listen. They vowed to keep burning incense to the queen of heaven with drink offerings, as they and their fathers had done in Judah's cities, claiming they had plenty of food then and only wanted since they stopped. Jeremiah answered that their idol worship had brought the desolation they were fleeing, and God swore His name would no longer be invoked by any man of Judah in Egypt. As a sign, Pharaoh-hophra would fall into his enemies' hands, just as Zedekiah had.",
  context:"To the Jews dwelling in Egypt at Migdol, Tahpanhes, Noph, and Pathros, who answered Jeremiah by defending the queen of heaven.",
  keyVerses:[
    { ref:"Jeremiah 44:16", text:"As for the word that thou hast spoken unto us in the name of the LORD, we will not hearken unto thee." },
    { ref:"Jeremiah 44:17", text:"But we will certainly do whatsoever thing goeth forth out of our own mouth, to burn incense unto the queen of heaven, and to pour out drink offerings unto her, as we have done, we, and our fathers, our kings, and our princes, in the cities of Judah, and in the streets of Jerusalem:" },
    { ref:"Jeremiah 44:28", text:"Yet a small number that escape the sword shall return out of the land of Egypt into the land of Judah, and all the remnant of Judah, that are gone into the land of Egypt to sojourn there, shall know whose words shall stand, mine, or theirs." }
  ],
  takeaway:"Idolatry promises plenty but delivers desolation; God's words stand against every defiant vow.",
  quiz:[
    { q:"Which female deity did the Jews in Egypt refuse to stop worshiping?", choices:["Ashtoreth of Zidon","Diana of the Ephesians","Chemosh's daughter","The queen of heaven"], a:3, why:"The people vowed to continue burning incense and pouring out drink offerings to the queen of heaven, as they and their fathers had done in Judah." },
    { q:"In which Egyptian cities were the Jews dwelling when this word came?", choices:["Migdol, Tahpanhes, Noph, and Pathros","Rabbah, Teman, and Bozrah","Carchemish and Riblah","Kedar and Hazor"], a:0, why:"The word came concerning the Jews in Egypt who dwelt at Migdol, at Tahpanhes, at Noph, and in the country of Pathros." },
    { q:"What sign did the Lord give that His word would stand against them?", choices:["The Nile would dry up","Fire would fall on Tahpanhes","Jerusalem would be rebuilt at once","Pharaoh-hophra would be given into the hand of his enemies"], a:3, why:"The Lord said He would give Pharaoh-hophra king of Egypt to his enemies, as He gave Zedekiah to Nebuchadrezzar, proving whose words would stand." }
  ] },
  { n:45, summary:"Baruch had written Jeremiah's words in a book at his dictation, and the weight of the message crushed him: Woe is me, for the Lord added grief to my sorrow, and I find no rest. In the fourth year of Jehoiakim the Lord sent him a personal answer. God was about to break down what He had built and pluck up what He had planted across the whole land, so Baruch's dreams of advancement had no place in such an hour: seekest thou great things for thyself? seek them not. Yet God gave him one firm promise to carry through the upheaval: his life would be given him for a prey, a surviving prize, in every place he went. It is a brief window into the cost carried by the prophet's faithful scribe.",
  context:"A short personal word to Baruch, given in the fourth year of Jehoiakim, when he had written the words in a book at Jeremiah's mouth.",
  keyVerses:[
    { ref:"Jeremiah 45:3", text:"Thou didst say, Woe is me now! for the LORD hath added grief to my sorrow; I fainted in my sighing, and I find no rest." },
    { ref:"Jeremiah 45:5", text:"And seekest thou great things for thyself? seek them not: for, behold, I will bring evil upon all flesh, saith the LORD: but thy life will I give unto thee for a prey in all places whither thou goest." }
  ],
  takeaway:"In collapsing times, seek not great things for yourself; God preserves those who serve Him faithfully.",
  quiz:[
    { q:"What had Baruch said in his discouragement?", choices:["Would God I had died in Josiah's days","Why does the king hate me?","Woe is me now! for the LORD hath added grief to my sorrow","I will go down to Egypt"], a:2, why:"Baruch said he fainted in his sighing and found no rest; grief had been added to his sorrow over what he wrote." },
    { q:"What did the Lord tell Baruch to stop seeking?", choices:["Great things for thyself","A wife and family","Riches in Babylon","A place in the king's court"], a:0, why:"Seekest thou great things for thyself? seek them not, for God was bringing evil on all flesh; Baruch's life would be his prize wherever he went." },
    { q:"What does the Lord's promise to Baruch teach about serving amid national collapse?", choices:["God preserves those who serve Him faithfully through turmoil","Faithful service guarantees comfort and fame","God's work stops when His servants despair","Personal ambition secures the future"], a:0, why:"Amid judgment on the whole land, the Lord promised Baruch his life for a prey in all places whither he went." }
  ] },
  { n:46, summary:"The first oracle against the Gentiles targets Egypt. At Carchemish by the Euphrates, in the fourth year of Jehoiakim, Nebuchadrezzar smashed the army of Pharaoh-necho. Jeremiah pictures Egypt's advance like a flooding river that suddenly turns back: swift soldiers stumble and fall toward the north by the river. Medicines in Gilead's balm would be used in vain on the virgin daughter of Egypt; her wound would not be cured. Pharaoh's vaunted power is dismissed as a noise that has passed its appointed time; Egypt, like a very fair heifer, faces destruction coming out of the north. Nebuchadrezzar would come like lumbermen felling a forest, and the multitude of No with Pharaoh and Egypt's gods and kings would be punished and delivered into his hand, though afterward Egypt would be inhabited as in days past. The chapter closes with comfort for Jacob: God would correct Israel in measure but never make a full end.",
  context:"The first oracle against the Gentiles, against Egypt's army defeated by Nebuchadrezzar at Carchemish in the fourth year of Jehoiakim.",
  keyVerses:[
    { ref:"Jeremiah 46:2", text:"Against Egypt, against the army of Pharaoh-necho king of Egypt, which was by the river Euphrates in Carchemish, which Nebuchadrezzar king of Babylon smote in the fourth year of Jehoiakim the son of Josiah king of Judah." },
    { ref:"Jeremiah 46:20", text:"Egypt is like a very fair heifer, but destruction cometh; it cometh out of the north." },
    { ref:"Jeremiah 46:27", text:"But fear not thou, O my servant Jacob, and be not dismayed, O Israel: for, behold, I will save thee from afar off, and thy seed from the land of their captivity; and Jacob shall return, and be in rest and at ease, and none shall make him afraid." }
  ],
  takeaway:"Powers that rise like a flood fall before God's judgment, but He corrects His people in measure, never a full end.",
  quiz:[
    { q:"At which battle site did Nebuchadrezzar smite the army of Pharaoh-necho?", choices:["Riblah in Hamath","Carchemish by the river Euphrates","Migdol by the Nile","Azekah in Judah"], a:1, why:"The oracle is against the army of Pharaoh-necho which was by the river Euphrates in Carchemish, which Nebuchadrezzar king of Babylon smote." },
    { q:"What animal image describes Egypt before destruction?", choices:["A raging lion","A foolish dove","A very fair heifer","A prancing horse"], a:2, why:"Egypt is like a very fair heifer, but destruction cometh; it cometh out of the north." },
    { q:"How does the oracle end, after all Egypt's doom?", choices:["A promise that Pharaoh would recover","Comfort for Jacob: God would correct Israel in measure but not make a full end","A command for Judah to ally with Egypt","Nothing about Israel at all"], a:1, why:"Fear not, O my servant Jacob: God would make a full end of all the nations where He drove Israel, but not a full end of Israel, correcting them in measure." }
  ] },
  { n:47, summary:"A short oracle against the Philistines comes before Pharaoh smote Gaza. Waters rise up out of the north like an overflowing flood, sweeping over the land and its cities until men cry and the inhabitants howl. At the stamping of strong horses and the rumble of chariot wheels, fathers are too feeble even to look back at their children. The day comes to spoil all the Philistines, the remnant of the country of Caphtor, and to cut off every helper left to Tyre and Zidon. Baldness covers Gaza; Ashkelon is cut off with the remnant of her valley, and the prophet asks how long the people will cut themselves in mourning. The chapter ends with a striking dialogue: O thou sword of the LORD, how long ere thou be quiet? The sword cannot rest, because the Lord has given it a charge against Ashkelon and the sea shore.",
  context:"A brief oracle against the Philistines, given before that Pharaoh smote Gaza.",
  keyVerses:[
    { ref:"Jeremiah 47:2", text:"Thus saith the LORD; Behold, waters rise up out of the north, and shall be an overflowing flood, and shall overflow the land, and all that is therein; the city, and them that dwell therein: then the men shall cry, and all the inhabitants of the land shall howl." },
    { ref:"Jeremiah 47:4", text:"Because of the day that cometh to spoil all the Philistines, and to cut off from Tyrus and Zidon every helper that remaineth: for the LORD will spoil the Philistines, the remnant of the country of Caphtor." },
    { ref:"Jeremiah 47:6", text:"O thou sword of the LORD, how long will it be ere thou be quiet? put up thyself into thy scabbard, rest, and be still." }
  ],
  takeaway:"The Lord's appointed judgment cannot be quieted until it has done His charge; He directs even the sword.",
  quiz:[
    { q:"What image describes the invasion coming against the Philistines?", choices:["Waters rising up out of the north like an overflowing flood","A swarm of locusts from the south","Fire falling from heaven","A wall of thorns"], a:0, why:"The Lord said waters would rise up out of the north as an overflowing flood, overflowing the land and its cities till men cried and the inhabitants howled." },
    { q:"Which Philistine cities are named in this judgment?", choices:["Sodom and Gomorrah","Gaza and Ashkelon","Nebo and Heshbon","Tyre and Damascus"], a:1, why:"Baldness is come upon Gaza; Ashkelon is cut off with the remnant of their valley, and the sword has a charge against Ashkelon and the sea shore." },
    { q:"What does the personified sword of the LORD teach about judgment?", choices:["Swords act independently of heaven","Judgment is random and mindless","God directs judgment to fulfill His appointed charge","Nations control their own outcomes"], a:2, why:"The sword could not be quiet because the LORD hath given it a charge against Ashkelon and against the sea shore: there hath he appointed it." }
  ] },
  { n:48, summary:"Moab's judgment oracle runs city by city: Nebo spoiled, Kiriathaim confounded, Heshbon scheming Moab's end, crying echoing from Horonaim, weeping on the ascent of Luhith. The reason is given plainly: Moab trusted in his works and his treasures, so he would be taken, and Chemosh would go into captivity with his priests and princes. The key image is wine left on its lees: Moab has been at ease from his youth, never emptied from vessel to vessel, so his taste remained unchanged; now wanderers would tip his vessels out and break the bottles. His pride is named again and again, and because he magnified himself against the Lord and mocked Israel, Moab would be broken like a vessel with no pleasure and destroyed from being a people. Fear, pit, and snare would catch every fugitive. Yet the oracle ends in mercy: in the latter days God would bring again the captivity of Moab.",
  context:"A long judgment oracle against Moab and its god Chemosh, ending with a promise of restoration in the latter days.",
  keyVerses:[
    { ref:"Jeremiah 48:7", text:"For because thou hast trusted in thy works and in thy treasures, thou shalt also be taken: and Chemosh shall go forth into captivity with his priests and his princes together." },
    { ref:"Jeremiah 48:11", text:"Moab hath been at ease from his youth, and he hath settled on his lees, and hath not been emptied from vessel to vessel, neither hath he gone into captivity: therefore his taste remained in him, and his scent is not changed." },
    { ref:"Jeremiah 48:47", text:"Yet will I bring again the captivity of Moab in the latter days, saith the LORD. Thus far is the judgment of Moab." }
  ],
  takeaway:"Pride and long ease invite God's pruning; settled comfort cannot protect those who magnify themselves against the Lord.",
  quiz:[
    { q:"What image describes Moab's long, unshaken ease?", choices:["A lion at rest in the reeds","A cedar by the waters","A dove in the rock","Wine settled on its lees, never emptied from vessel to vessel"], a:3, why:"Moab had been at ease from his youth and settled on his lees, never emptied from vessel to vessel, so his taste remained in him; now wanderers would empty his vessels and break the bottles." },
    { q:"Which god of Moab would go into captivity with his priests and princes?", choices:["Chemosh","Baal","Molech","Dagon"], a:0, why:"Because Moab trusted in his works and treasures, he would be taken, and Chemosh shall go forth into captivity with his priests and his princes together." },
    { q:"How does the long judgment on Moab end?", choices:["Moab shall cease from being a nation for ever","Yet will I bring again the captivity of Moab in the latter days","Chemosh will judge Babylon","Israel shall serve Moab again"], a:1, why:"After all the judgment, the Lord promised to bring again the captivity of Moab in the latter days, closing with, Thus far is the judgment of Moab." }
  ] },
  { n:49, summary:"This chapter collects shorter oracles against five neighbors. The Ammonites had inherited Gad while Israel lacked an heir, so an alarm of war would sound in Rabbah and leave it a desolate heap, though afterward God would restore their captivity. Edom, famed for wisdom in Teman and safety in clefts of rock, would be stripped more thoroughly than grapegatherers and thieves leave a field; though she made her nest as high as the eagle, God would bring her down, leaving a desolation like Sodom and Gomorrah, while widows and fatherless were told to trust in Him. Damascus would grow feeble, her young men falling in her streets, fire consuming the palaces of Ben-hadad. Kedar and Hazor, wealthy and unwalled, would be spoiled by Nebuchadrezzar, their camels carried off. Elam's great bow would be broken and its people scattered to the four winds, yet in the latter days God would bring again the captivity of Elam.",
  context:"Oracles against the Ammonites, Edom, Damascus, Kedar and Hazor, and Elam; the word on Elam came in the beginning of Zedekiah's reign.",
  keyVerses:[
    { ref:"Jeremiah 49:7", text:"Concerning Edom, thus saith the LORD of hosts; Is wisdom no more in Teman? is counsel perished from the prudent? is their wisdom vanished?" },
    { ref:"Jeremiah 49:16", text:"Thy terribleness hath deceived thee, and the pride of thine heart, O thou that dwellest in the clefts of the rock, that holdest the height of the hill: though thou shouldest make thy nest as high as the eagle, I will bring thee down from thence, saith the LORD." },
    { ref:"Jeremiah 49:35", text:"Thus saith the LORD of hosts; Behold, I will break the bow of Elam, the chief of their might." }
  ],
  takeaway:"Wisdom, wealth, and strongholds cannot save a nation from God's day of visitation, but mercy follows in the latter days.",
  quiz:[
    { q:"Whose wisdom was said to have perished in Edom?", choices:["Teman","Bozrah","Dedan","Rabbah"], a:0, why:"The Lord asked, Is wisdom no more in Teman? is counsel perished from the prudent? Edom's famed wisdom could not save it." },
    { q:"What weapon is singled out as Elam's chief might?", choices:["The chariot","The sword","The sling","The bow"], a:3, why:"The Lord said, I will break the bow of Elam, the chief of their might; Elam would then be scattered to the four winds." },
    { q:"Where would the alarm of war sound against the Ammonites?", choices:["Rabbah","Heshbon","Kedar","Damascus"], a:0, why:"The Lord said the days come that I will cause an alarm of war to be heard in Rabbah of the Ammonites; and it shall be a desolate heap." }
  ] },
  { n:50, summary:"The word against Babylon opens with a proclamation to the nations: Babylon is taken, Bel is confounded, Merodach is broken in pieces. Out of the north an assembly of great nations comes against her, their arrows never missing, and the land of Chaldea becomes a spoil. Into that scene Jeremiah folds Israel's story: my people hath been lost sheep, misled by shepherds, devoured first by the king of Assyria, and last broken in bone by Nebuchadrezzar. Because Babylon destroyed God's heritage and rejoiced doing it, her punishment would match her work, as she did unto Zion: vengeance. The city that hammered the whole earth would itself be cut asunder and broken; a snare catches her unaware because she strove against the Lord. Yet for Israel and Judah the same days hold pardon: their iniquity would be sought and not found, and their strong Redeemer would thoroughly plead their cause and give rest to the land.",
  context:"The first of two long oracles that Jeremiah the prophet spoke against Babylon and the land of the Chaldeans.",
  keyVerses:[
    { ref:"Jeremiah 50:2", text:"Declare ye among the nations, and publish, and set up a standard; publish, and conceal not: say, Babylon is taken, Bel is confounded, Merodach is broken in pieces; her idols are confounded, her images are broken in pieces." },
    { ref:"Jeremiah 50:17", text:"Israel is a scattered sheep; the lions have driven him away: first the king of Assyria hath devoured him; and last this Nebuchadrezzar king of Babylon hath broken his bones." },
    { ref:"Jeremiah 50:23", text:"How is the hammer of the whole earth cut asunder and broken! how is Babylon become a desolation among the nations!" }
  ],
  takeaway:"The hammer of the whole earth is broken before the Lord, yet His redeemed find pardon and a Redeemer who pleads their cause.",
  quiz:[
    { q:"What name is given to Babylon that will be cut asunder and broken?", choices:["The golden city of the sun","The hammer of the whole earth","The iron mountain","The mother of nations"], a:1, why:"The oracle cries, How is the hammer of the whole earth cut asunder and broken! how is Babylon become a desolation among the nations!" },
    { q:"Which gods are named as confounded when Babylon falls?", choices:["Bel and Merodach","Chemosh and Molech","Nisroch and Rimmon","Diana and Artemis"], a:0, why:"The proclamation says, Babylon is taken, Bel is confounded, Merodach is broken in pieces; her idols are confounded." },
    { q:"How does chapter 50 describe Israel before Babylon's fall?", choices:["A sleeping giant","A gold chain grown rusty","A lantern gone out","A scattered sheep the lions drove away"], a:3, why:"Israel is a scattered sheep; first the king of Assyria devoured him, and last Nebuchadrezzar broke his bones, but his strong Redeemer would plead his cause." }
  ] },
  { n:51, summary:"The second Babylon oracle drives the judgment home. Babylon had been a golden cup in the Lord's hand, making all the earth drunken and mad; now her judgment reaches to heaven, and God's people must flee out of her midst, each saving his soul, before they are cut off in her iniquity. The spirit of the kings of the Medes is raised up for the vengeance of the Lord's temple. Against idols that are falsehood without breath, the chapter sets the Creator who made earth by His power and stretches out heaven by His understanding; Israel, His battle axe, would break in pieces nations, kingdoms, horse and rider. Babylon, the destroying mountain, would be rolled down and become a burnt mountain, a heap, a dwelling for dragons, her broad walls broken and high gates burned. Jeremiah had Seraiah read this book in Babylon, then tie a stone to it and sink it in the Euphrates: so shall Babylon sink, and not rise.",
  context:"The second oracle against Babylon, ending with Jeremiah's charge to Seraiah to read the book in Babylon and sink it in the Euphrates.",
  keyVerses:[
    { ref:"Jeremiah 51:7", text:"Babylon hath been a golden cup in the LORD's hand, that made all the earth drunken: the nations have drunken of her wine; therefore the nations are mad." },
    { ref:"Jeremiah 51:63", text:"And it shall be, when thou hast made an end of reading this book, that thou shalt bind a stone to it, and cast it into the midst of Euphrates:" },
    { ref:"Jeremiah 51:64", text:"And thou shalt say, Thus shall Babylon sink, and shall not rise from the evil that I will bring upon her: and they shall be weary." }
  ],
  takeaway:"Babylon's golden cup of corruption will be dashed; flee what God judges, for His word stands forever.",
  quiz:[
    { q:"What had Babylon been in the Lord's hand that made the earth drunken?", choices:["A two-edged sword","A threshing sledge","A golden cup","A stone of stumbling"], a:2, why:"Babylon hath been a golden cup in the LORD's hand, that made all the earth drunken: the nations have drunken of her wine, therefore the nations are mad." },
    { q:"What was Seraiah told to do with the book against Babylon after reading it?", choices:["Seal it and hide it in an earthen vessel","Deliver it to the king of Babylon","Bind a stone to it and cast it into the midst of the Euphrates","Burn it in the brickkiln"], a:2, why:"After reading the book in Babylon he was to bind a stone to it, cast it into the Euphrates, and say, Thus shall Babylon sink, and shall not rise." },
    { q:"Which peoples did the Lord raise up against Babylon?", choices:["The kings of Egypt","The princes of Ammon","The armies of Damascus","The kings of the Medes"], a:3, why:"The LORD hath raised up the spirit of the kings of the Medes, for his device is against Babylon, to destroy it." }
  ] },
  { n:52, summary:"The appendix retells Jerusalem's fall. Zedekiah, twenty-one when he began to reign, rebelled against Babylon; in his ninth year Nebuchadrezzar's army besieged Jerusalem, and the siege lasted to his eleventh year, till famine left no bread. When the city was broken up, the men of war fled by night toward the plain, but the Chaldeans overtook Zedekiah in the plains of Jericho. At Riblah the king of Babylon slew his sons before his eyes and the princes of Judah, then put out Zedekiah's eyes, bound him, and imprisoned him in Babylon till his death. In the fifth month Nebuzar-adan burned the house of the Lord, the king's house, and every great house, broke down the walls, carried off the temple brass and vessels, and executed priests and officials at Riblah. The captives are counted year by year, four thousand six hundred in all. The book ends quietly: in the thirty-seventh year of Jehoiachin's captivity, Evil-merodach lifted up his head, spoke kindly, and gave him a daily portion for life.",
  context:"A historical appendix retelling Jerusalem's fall under Zedekiah, the burning of the temple, the counted captives, and Jehoiachin's release in Babylon.",
  keyVerses:[
    { ref:"Jeremiah 52:11", text:"Then he put out the eyes of Zedekiah; and the king of Babylon bound him in chains, and carried him to Babylon, and put him in prison till the day of his death." },
    { ref:"Jeremiah 52:13", text:"And burned the house of the LORD, and the king's house; and all the houses of Jerusalem, and all the houses of the great men, burned he with fire:" },
    { ref:"Jeremiah 52:31", text:"And it came to pass in the seven and thirtieth year of the captivity of Jehoiachin king of Judah, in the twelfth month, in the five and twentieth day of the month, that Evil-merodach king of Babylon in the first year of his reign lifted up the head of Jehoiachin king of Judah, and brought him forth out of prison," }
  ],
  takeaway:"God's warnings were fulfilled to the letter, yet even in exile He preserved a king's line and a remnant of hope.",
  quiz:[
    { q:"Which king of Babylon finally released Jehoiachin from prison?", choices:["Nebuchadrezzar","Nebuzar-adan","Belshazzar","Evil-merodach"], a:3, why:"In the thirty-seventh year of Jehoiachin's captivity, Evil-merodach, in the first year of his reign, lifted up the head of Jehoiachin and brought him forth out of prison." },
    { q:"How long did the final siege of Jerusalem last, from beginning to breach?", choices:["From the ninth year of Zedekiah to his eleventh","Forty days in the tenth month","Seven years of blockade","Three months of famine"], a:0, why:"Nebuchadrezzar came against Jerusalem in Zedekiah's ninth year, tenth month, and the city was besieged unto the eleventh year of king Zedekiah." },
    { q:"What became of Zedekiah after he was captured?", choices:["He was restored as a vassal king","He escaped to Egypt with his army","He was made a priest in Babylon","His sons were slain before his eyes, then his eyes were put out, and he died in prison in Babylon"], a:3, why:"At Riblah the king of Babylon slew Zedekiah's sons before his eyes, put out his eyes, bound him in chains, and kept him in prison till the day of his death." }
  ] }
);
